package com.coffeeshop.controller;import com.coffeeshop.dto.ExpenseCommands;import com.coffeeshop.model.ExpenseModels.*;import com.coffeeshop.security.ApplicationSession;import com.coffeeshop.service.ExpenseService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.collections.FXCollections;import javafx.fxml.FXML;import javafx.geometry.Insets;import javafx.scene.control.*;import javafx.scene.layout.GridPane;import java.math.BigDecimal;import java.time.*;import java.util.*;import java.util.concurrent.CompletableFuture;public final class ExpenseController{private final ExpenseService service;private final ApplicationSession session;private Catalog catalog;@FXML private TextField searchField;@FXML private ChoiceBox<String>categoryFilter;@FXML private TableView<Expense>expenseTable;@FXML private TableColumn<Expense,String>numberColumn,dateColumn,categoryColumn,descriptionColumn,amountColumn,userColumn;@FXML private TableView<Category>categoryTable;@FXML private TableColumn<Category,String>categoryCodeColumn,categoryNameColumn,categoryStatusColumn;@FXML private Label messageLabel;@FXML private Button editExpenseButton,editCategoryButton,toggleCategoryButton;public ExpenseController(ExpenseService s,ApplicationSession a){service=Objects.requireNonNull(s);session=Objects.requireNonNull(a);}@FXML private void initialize(){numberColumn.setCellValueFactory(v->text(v.getValue().number()));dateColumn.setCellValueFactory(v->text(v.getValue().expensedAt().toLocalDate().toString()));categoryColumn.setCellValueFactory(v->text(v.getValue().categoryName()));descriptionColumn.setCellValueFactory(v->text(orDash(v.getValue().description())));amountColumn.setCellValueFactory(v->text(v.getValue().amount().toPlainString()));userColumn.setCellValueFactory(v->text(v.getValue().recordedBy()));categoryCodeColumn.setCellValueFactory(v->text(v.getValue().code()));categoryNameColumn.setCellValueFactory(v->text(v.getValue().name()));categoryStatusColumn.setCellValueFactory(v->text(v.getValue().active()?"Active":"Inactive"));searchField.textProperty().addListener((o,a,b)->filter());categoryFilter.valueProperty().addListener((o,a,b)->filter());expenseTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->editExpenseButton.setDisable(b==null));categoryTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->categorySelection(b));refresh();}@FXML private void refresh(){CompletableFuture.supplyAsync(service::catalog).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load expenses.");return;}catalog=v;categoryTable.getItems().setAll(v.categories());categoryFilter.getItems().setAll("All");categoryFilter.getItems().addAll(v.categories().stream().map(Category::name).toList());categoryFilter.setValue("All");filter();messageLabel.setText("");}));}private void filter(){if(catalog==null)return;String q=searchField.getText().trim().toLowerCase(),cat=categoryFilter.getValue();expenseTable.getItems().setAll(catalog.expenses().stream().filter(e->(cat==null||"All".equals(cat)||e.categoryName().equals(cat))&&(q.isEmpty()||(e.number()+" "+e.categoryName()+" "+Objects.toString(e.description(),"")+" "+Objects.toString(e.reference(),"")).toLowerCase().contains(q))).toList());}@FXML private void addCategory(){categoryDialog(null).ifPresent(this::saveCategory);}@FXML private void editCategory(){Category c=categoryTable.getSelectionModel().getSelectedItem();if(c!=null)categoryDialog(c).ifPresent(this::saveCategory);}@FXML private void toggleCategory(){Category c=categoryTable.getSelectionModel().getSelectedItem();if(c!=null)write(()->service.setCategoryActive(c,!c.active()),"Category updated.");}@FXML private void addExpense(){expenseDialog(null).ifPresent(this::saveExpense);}@FXML private void editExpense(){Expense e=expenseTable.getSelectionModel().getSelectedItem();if(e!=null)expenseDialog(e).ifPresent(this::saveExpense);}private Optional<ExpenseCommands.Category>categoryDialog(Category c){Dialog<ExpenseCommands.Category>d=dialog(c==null?"Add expense category":"Edit expense category");TextField code=f(c==null?null:c.code()),name=f(c==null?null:c.name());CheckBox active=new CheckBox("Active");active.setSelected(c==null||c.active());GridPane g=form();field(g,0,"Code",code);field(g,1,"Name",name);g.add(active,1,2);d.getDialogPane().setContent(g);d.setResultConverter(b->ok(b)?new ExpenseCommands.Category(c==null?null:c.id(),code.getText(),name.getText(),active.isSelected(),c==null?null:c.version()):null);return d.showAndWait();}private Optional<ExpenseCommands.Expense>expenseDialog(Expense e){Dialog<ExpenseCommands.Expense>d=dialog(e==null?"Add expense":"Edit expense");ComboBox<Category>category=new ComboBox<>(FXCollections.observableArrayList(catalog.categories().stream().filter(Category::active).toList()));category.setMaxWidth(Double.MAX_VALUE);if(e!=null)catalog.categories().stream().filter(c->c.id()==e.categoryId()).findFirst().ifPresent(category::setValue);DatePicker date=new DatePicker(e==null?LocalDate.now():e.expensedAt().toLocalDate());TextField amount=f(e==null?null:e.amount().toPlainString()),description=f(e==null?null:e.description()),reference=f(e==null?null:e.reference());TextArea notes=new TextArea(e==null||e.notes()==null?"":e.notes());notes.setPrefRowCount(3);GridPane g=form();field(g,0,"Category",category);field(g,1,"Expense date",date);field(g,2,"Amount",amount);field(g,3,"Description",description);field(g,4,"Reference",reference);field(g,5,"Notes",notes);d.getDialogPane().setContent(g);d.setResultConverter(b->{if(!ok(b)||category.getValue()==null)return null;BigDecimal value;try{value=new BigDecimal(amount.getText());}catch(Exception x){value=null;}return new ExpenseCommands.Expense(e==null?null:e.id(),category.getValue().id(),date.getValue()==null?null:date.getValue().atStartOfDay(),value,description.getText(),reference.getText(),notes.getText(),e==null?null:e.version());});return d.showAndWait();}private void saveCategory(ExpenseCommands.Category q){write(()->service.saveCategory(q),"Category saved.");}private void saveExpense(ExpenseCommands.Expense q){write(()->service.saveExpense(q,session.currentUser().orElseThrow().userId()),"Expense saved.");}private void write(Runnable r,String ok){CompletableFuture.runAsync(r).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText(ok);}else messageLabel.setText(message(e));}));}private void categorySelection(Category c){editCategoryButton.setDisable(c==null);toggleCategoryButton.setDisable(c==null);toggleCategoryButton.setText(c==null||c.active()?"Deactivate":"Activate");}private static <T>Dialog<T>dialog(String t){Dialog<T>d=new Dialog<>();d.setTitle(t);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,new ButtonType("Save",ButtonBar.ButtonData.OK_DONE));return d;}private static boolean ok(ButtonType b){return b.getButtonData()==ButtonBar.ButtonData.OK_DONE;}private static GridPane form(){GridPane g=new GridPane();g.setHgap(12);g.setVgap(8);g.setPadding(new Insets(8));return g;}private static void field(GridPane g,int r,String n,Control c){g.add(new Label(n),0,r);c.setMaxWidth(Double.MAX_VALUE);g.add(c,1,r);}private static TextField f(String s){return new TextField(s==null?"":s);}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String orDash(String s){return s==null||s.isBlank()?"-":s;}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to update expense data.";}}
